mapper.select:
SELECT COUNT(*) FROM NOTICE N WHERE 1=1

	AND N.TITLE LIKE '%' || #{search.keyword} || '%'


	AND N.NOTICE_TYPE=#{search.noticeType}


	AND N.STATUS=#{search.status}

SELECT * FROM (
SELECT N.NOTICE_CODE,N.MANAGER_CODE,N.TITLE AS NOTICE_TITLE,
N.NOTICE_TYPE,N.INPUT_DATE AS REGISTERED_DATE,M.ID AS
WRITER_ID,N.STATUS,
ROW_NUMBER() OVER(ORDER BY N.INPUT_DATE DESC,N.NOTICE_CODE DESC) RN
FROM NOTICE N JOIN MANAGER M ON N.MANAGER_CODE=M.MANAGER_CODE
WHERE 1=1

	AND N.TITLE LIKE '%' || #{search.keyword} || '%'


	AND N.NOTICE_TYPE=#{search.noticeType}


	AND N.STATUS=#{search.status}

)
WHERE RN BETWEEN #{search.startRow} AND #{search.endRow}
